    "code": "import { BlurVignette, BlurVignetteArticle } from '@/registry/ui-layouts/blur-vignette';\nimport { cn } from '@/lib/utils';\nimport Image from 'next/image';\nimport React from 'react';\n\nfunction Blurvignettevideo() {\n  return (\n    <>\n      <BlurVignette\n        radius='24px'\n        inset='10px'\n        transitionLength='100px'\n        blur='15px'\n        classname='h-96 w-full overflow-hidden'\n      >\n        <video\n          autoPlay={true}\n          muted\n          loop\n          content='true'\n          className='w-full  h-full object-cover  transition-all hover:scale-110'\n        >\n          <source\n            src='https://cdn.pixabay.com/video/2023/10/19/185726-876210695_large.mp4'\n            type='video/mp4'\n          />\n        </video>\n        <BlurVignetteArticle />\n      </BlurVignette>\n    </>\n  );\n}\n\nexport default Blurvignettevideo;",
    "demoCode": "import Cmp from \"@/registry/ui-layouts/blurvignettevideo\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
