    "code": "'use client';\nimport { SpotLightItem, Spotlight } from '@/registry/ui-layouts/spotlight';\nimport Image from 'next/image';\nimport React from 'react';\n\nexport default function SpotlightCard4() {\n  return (\n    <div className='relative bg-black sm:p-8 px-4 rounded-md'>\n      <Spotlight className='sm:w-120 w-full mx-auto' ProximitySpotlight={true}>\n        <SpotLightItem>\n          <div className=\"relative text-center z-10 sm:px-8 px-4 py-6 rounded-lg w-fit  bg-[url('https://res.cloudinary.com/dzl9yxixg/image/upload/sub-grid_hnhyvi.png')] bg-cover   bg-black h-full mx-auto\">\n            <>\n              <Image\n                src={'/star_tb9ivg.webp'}\n                alt='grid'\n                width={600}\n                className='w-fit mx-auto '\n                height={600}\n              />\n              <h1 className='text-2xl pt-5 font-semibold tracking-tight text-white'>\n                Seamless Animation For All\n              </h1>\n              <p className='pt-2 lg:text-base text-sm  text-neutral-300 capitalize'>\n                Effortlessly connect with today's leading technologies including React, TypeScript,\n                Next.js, Tailwind CSS, Motion, and Cypress.\n              </p>\n            </>\n          </div>\n        </SpotLightItem>\n      </Spotlight>\n    </div>\n  );\n}",
