    "code": "\"use client\";\n\nimport {\n  AlignCenterIcon,\n  AlignJustifyIcon,\n  AlignLeftIcon,\n  AlignRightIcon,\n} from \"lucide-react\";\nimport { useState } from \"react\";\n\nimport {\n  ToggleGroup,\n  ToggleGroupItem,\n} from \"@/components/ui/toggle-group\";\n\nexport default function Component() {\n  const [value, setValue] = useState<string>(\"center\");\n\n  return (\n    <ToggleGroup\n      className=\"inline-flex divide-x divide-background\"\n      onValueChange={(value) => {\n        if (value) setValue(value);\n      }}\n      type=\"single\"\n      value={value}\n    >\n      <ToggleGroupItem\n        aria-label=\"Align Left\"\n        className=\"bg-primary/80 text-primary-foreground hover:bg-primary hover:text-primary-foreground data-[state=on]:bg-primary data-[state=on]:text-primary-foreground\"\n        value=\"left\"\n      >\n        <AlignLeftIcon aria-hidden=\"true\" size={16} />\n      </ToggleGroupItem>\n      <ToggleGroupItem\n        aria-label=\"Align Center\"\n        className=\"bg-primary/80 text-primary-foreground hover:bg-primary hover:text-primary-foreground data-[state=on]:bg-primary data-[state=on]:text-primary-foreground\"\n        value=\"center\"\n      >\n        <AlignCenterIcon aria-hidden=\"true\" size={16} />\n      </ToggleGroupItem>\n      <ToggleGroupItem\n        aria-label=\"Align Right\"\n        className=\"bg-primary/80 text-primary-foreground hover:bg-primary hover:text-primary-foreground data-[state=on]:bg-primary data-[state=on]:text-primary-foreground\"\n        value=\"right\"\n      >\n        <AlignRightIcon aria-hidden=\"true\" size={16} />\n      </ToggleGroupItem>\n      <ToggleGroupItem\n        aria-label=\"Align Justify\"\n        className=\"bg-primary/80 text-primary-foreground hover:bg-primary hover:text-primary-foreground data-[state=on]:bg-primary data-[state=on]:text-primary-foreground\"\n        value=\"justify\"\n      >\n        <AlignJustifyIcon aria-hidden=\"true\" size={16} />\n      </ToggleGroupItem>\n    </ToggleGroup>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-107\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
