    "code": "import { useId } from \"react\";\n\nimport { Label } from \"@/components/ui/label\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/components/ui/select\";\n\nexport default function Component() {\n  const id = useId();\n  return (\n    <div className=\"*:not-first:mt-2\">\n      <Label htmlFor={id}>Options with portrait</Label>\n      <Select defaultValue=\"1\">\n        <SelectTrigger\n          className=\"h-auto ps-2 text-left [&>span]:flex [&>span]:items-center [&>span]:gap-2 [&>span_img]:shrink-0\"\n          id={id}\n        >\n          <SelectValue placeholder=\"Choose a plan\" />\n        </SelectTrigger>\n        <SelectContent className=\"[&_*[role=option]>span]:start-auto [&_*[role=option]>span]:end-2 [&_*[role=option]]:ps-2 [&_*[role=option]]:pe-8\">\n          <SelectItem value=\"1\">\n            <span className=\"flex items-center gap-2\">\n              <img\n                alt=\"Jenny Hamilton\"\n                className=\"rounded-full\"\n                height={40}\n                src=\"/origin/avatar-40-01.jpg\"\n                width={40}\n              />\n              <span>\n                <span className=\"block font-medium\">Jenny Hamilton</span>\n                <span className=\"mt-0.5 block text-muted-foreground text-xs\">\n                  @jennycodes\n                </span>\n              </span>\n            </span>\n          </SelectItem>\n          <SelectItem value=\"2\">\n            <span className=\"flex items-center gap-2\">\n              <img\n                alt=\"Paul Smith\"\n                className=\"rounded-full\"\n                height={40}\n                src=\"/origin/avatar-40-02.jpg\"\n                width={40}\n              />\n              <span>\n                <span className=\"block font-medium\">Paul Smith</span>\n                <span className=\"mt-0.5 block text-muted-foreground text-xs\">\n                  @paulsmith\n                </span>\n              </span>\n            </span>\n          </SelectItem>\n          <SelectItem value=\"3\">\n            <span className=\"flex items-center gap-2\">\n              <img\n                alt=\"Luna Wyen\"\n                className=\"rounded-full\"\n                height={40}\n                src=\"/origin/avatar-40-03.jpg\"\n                width={40}\n              />\n              <span>\n                <span className=\"block font-medium\">Luna Wyen</span>\n                <span className=\"mt-0.5 block text-muted-foreground text-xs\">\n                  @wyen.luna\n                </span>\n              </span>\n            </span>\n          </SelectItem>\n        </SelectContent>\n      </Select>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-228\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
