    "code": "\"use client\";\n\nimport { useSliderWithInput } from \"@/registry/origin-ui/use-slider-with-input\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Slider } from \"@/components/ui/slider\";\n\nexport default function Component() {\n  const minValue = 0;\n  const maxValue = 200;\n  const initialValue = [50, 150];\n\n  const {\n    sliderValue,\n    inputValues,\n    validateAndUpdateValue,\n    handleInputChange,\n    handleSliderChange,\n  } = useSliderWithInput({ initialValue, maxValue, minValue });\n\n  return (\n    <div className=\"*:not-first:mt-3\">\n      <Label>Dual range slider with input</Label>\n      <div className=\"flex items-center gap-4\">\n        <Input\n          aria-label=\"Enter minimum value\"\n          className=\"h-8 w-12 px-2 py-1\"\n          inputMode=\"decimal\"\n          onBlur={() => validateAndUpdateValue(inputValues[0], 0)}\n          onChange={(e) => handleInputChange(e, 0)}\n          onKeyDown={(e) => {\n            if (e.key === \"Enter\") {\n              validateAndUpdateValue(inputValues[0], 0);\n            }\n          }}\n          type=\"text\"\n          value={inputValues[0]}\n        />\n        <Slider\n          aria-label=\"Dual range slider with input\"\n          className=\"grow\"\n          max={maxValue}\n          min={minValue}\n          onValueChange={handleSliderChange}\n          value={sliderValue}\n        />\n        <Input\n          aria-label=\"Enter maximum value\"\n          className=\"h-8 w-12 px-2 py-1\"\n          inputMode=\"decimal\"\n          onBlur={() => validateAndUpdateValue(inputValues[1], 1)}\n          onChange={(e) => handleInputChange(e, 1)}\n          onKeyDown={(e) => {\n            if (e.key === \"Enter\") {\n              validateAndUpdateValue(inputValues[1], 1);\n            }\n          }}\n          type=\"text\"\n          value={inputValues[1]}\n        />\n      </div>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-258\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
