    "code": "import { XIcon } from \"lucide-react\";\n\nimport { Button } from \"@/components/ui/button\";\n\nexport default function Component() {\n  return (\n    // To make the notification fixed, add classes like `fixed bottom-4 right-4` to the container element.\n    <div className=\"z-50 max-w-[400px] rounded-md border bg-background p-4 shadow-lg\">\n      <div className=\"flex gap-3\">\n        <img\n          alt=\"Mary Palmer\"\n          className=\"size-9 rounded-full\"\n          height={32}\n          src=\"https://i.pravatar.cc/80?img=11\"\n          width={32}\n        />\n        <div className=\"flex grow flex-col gap-3\">\n          <div className=\"space-y-1\">\n            <p className=\"text-muted-foreground text-sm\">\n              <a\n                className=\"font-medium text-foreground hover:underline\"\n                href=\"#\"\n              >\n                Mary Palmer\n              </a>{\" \"}\n              mentioned you in{\" \"}\n              <a\n                className=\"font-medium text-foreground hover:underline\"\n                href=\"#\"\n              >\n                project-campaign-02\n              </a>\n              .\n            </p>\n            <p className=\"text-muted-foreground text-xs\">2 min ago</p>\n          </div>\n          <div className=\"flex gap-2\">\n            <Button size=\"sm\">Accept</Button>\n            <Button size=\"sm\" variant=\"outline\">\n              Decline\n            </Button>\n          </div>\n        </div>\n        <Button\n          aria-label=\"Close notification\"\n          className=\"group -my-1.5 -me-2 size-8 shrink-0 p-0 hover:bg-transparent\"\n          variant=\"ghost\"\n        >\n          <XIcon\n            aria-hidden=\"true\"\n            className=\"opacity-60 transition-opacity group-hover:opacity-100\"\n            size={16}\n          />\n        </Button>\n      </div>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-295\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
