    "demoCode": "\"use client\";\n\nimport { Toaster } from \"@/components/ui/sonner\";\nimport Cmp from \"@/registry/origin-ui/comp-299\";\n\nexport default function Demo() {\n  return (\n    <>\n      <Cmp />\n      <Toaster />\n    </>\n  );\n}"
