    "code": "import { CircleUserRoundIcon } from \"lucide-react\";\n\nimport { Button } from \"@/components/ui/button\";\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuGroup,\n  DropdownMenuItem,\n  DropdownMenuLabel,\n  DropdownMenuSeparator,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\";\n\nexport default function Component() {\n  return (\n    <DropdownMenu>\n      <DropdownMenuTrigger asChild>\n        <Button aria-label=\"Open account menu\" size=\"icon\" variant=\"outline\">\n          <CircleUserRoundIcon aria-hidden=\"true\" size={16} />\n        </Button>\n      </DropdownMenuTrigger>\n      <DropdownMenuContent className=\"max-w-64\">\n        <DropdownMenuLabel className=\"flex flex-col\">\n          <span>Signed in as</span>\n          <span className=\"font-normal text-foreground text-xs\">\n            k.kennedy@coss.com\n          </span>\n        </DropdownMenuLabel>\n        <DropdownMenuSeparator />\n        <DropdownMenuGroup>\n          <DropdownMenuItem>Option 1</DropdownMenuItem>\n          <DropdownMenuItem>Option 2</DropdownMenuItem>\n          <DropdownMenuItem>Option 3</DropdownMenuItem>\n        </DropdownMenuGroup>\n        <DropdownMenuSeparator />\n        <DropdownMenuItem>Logout</DropdownMenuItem>\n      </DropdownMenuContent>\n    </DropdownMenu>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-375\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
