    "code": "import {\n  BoltIcon,\n  BookOpenIcon,\n  CircleUserRoundIcon,\n  Layers2Icon,\n  LogOutIcon,\n  PinIcon,\n  UserPenIcon,\n} from \"lucide-react\";\n\nimport { Button } from \"@/components/ui/button\";\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuGroup,\n  DropdownMenuItem,\n  DropdownMenuLabel,\n  DropdownMenuSeparator,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\";\n\nexport default function Component() {\n  return (\n    <DropdownMenu>\n      <DropdownMenuTrigger asChild>\n        <Button aria-label=\"Open account menu\" size=\"icon\" variant=\"outline\">\n          <CircleUserRoundIcon aria-hidden=\"true\" size={16} />\n        </Button>\n      </DropdownMenuTrigger>\n      <DropdownMenuContent className=\"max-w-64\">\n        <DropdownMenuLabel className=\"flex items-start gap-3\">\n          <img\n            alt=\"Avatar\"\n            className=\"shrink-0 rounded-full\"\n            height={32}\n            src=\"/origin/avatar.jpg\"\n            width={32}\n          />\n          <div className=\"flex min-w-0 flex-col\">\n            <span className=\"truncate font-medium text-foreground text-sm\">\n              Keith Kennedy\n            </span>\n            <span className=\"truncate font-normal text-muted-foreground text-xs\">\n              k.kennedy@coss.com\n            </span>\n          </div>\n        </DropdownMenuLabel>\n        <DropdownMenuSeparator />\n        <DropdownMenuGroup>\n          <DropdownMenuItem>\n            <BoltIcon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n            <span>Option 1</span>\n          </DropdownMenuItem>\n          <DropdownMenuItem>\n            <Layers2Icon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n            <span>Option 2</span>\n          </DropdownMenuItem>\n          <DropdownMenuItem>\n            <BookOpenIcon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n            <span>Option 3</span>\n          </DropdownMenuItem>\n        </DropdownMenuGroup>\n        <DropdownMenuSeparator />\n        <DropdownMenuGroup>\n          <DropdownMenuItem>\n            <PinIcon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n            <span>Option 4</span>\n          </DropdownMenuItem>\n          <DropdownMenuItem>\n            <UserPenIcon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n            <span>Option 5</span>\n          </DropdownMenuItem>\n        </DropdownMenuGroup>\n        <DropdownMenuSeparator />\n        <DropdownMenuItem>\n          <LogOutIcon aria-hidden=\"true\" className=\"opacity-60\" size={16} />\n          <span>Logout</span>\n        </DropdownMenuItem>\n      </DropdownMenuContent>\n    </DropdownMenu>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-376\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
