    "code": "import { ArrowLeftIcon, ArrowRightIcon } from \"lucide-react\";\n\nimport { Button } from \"@/components/ui/button\";\nimport {\n  Pagination,\n  PaginationContent,\n  PaginationItem,\n} from \"@/components/ui/pagination\";\n\ntype PaginationProps = {\n  currentPage: number;\n  totalPages: number;\n};\n\nexport default function Component({\n  currentPage,\n  totalPages,\n}: PaginationProps) {\n  return (\n    <Pagination>\n      <PaginationContent className=\"w-full justify-between gap-3\">\n        <PaginationItem>\n          <Button\n            aria-disabled={currentPage === 1 ? true : undefined}\n            className=\"group aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            role={currentPage === 1 ? \"link\" : undefined}\n            variant=\"ghost\"\n          >\n            <ArrowLeftIcon\n              aria-hidden=\"true\"\n              className=\"-ms-1 group-hover:-translate-x-0.5 opacity-60 transition-transform\"\n              size={16}\n            />\n            Previous\n          </Button>\n        </PaginationItem>\n        <PaginationItem>\n          <Button\n            aria-disabled={currentPage === totalPages ? true : undefined}\n            className=\"group aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            role={currentPage === totalPages ? \"link\" : undefined}\n            variant=\"ghost\"\n          >\n            Next\n            <ArrowRightIcon\n              aria-hidden=\"true\"\n              className=\"-me-1 opacity-60 transition-transform group-hover:translate-x-0.5\"\n              size={16}\n            />\n          </Button>\n        </PaginationItem>\n      </PaginationContent>\n    </Pagination>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { useState } from \"react\";\n\nimport Cmp from \"@/registry/origin-ui/comp-455\";\n\nexport default function Demo() {\n  const [page, setPage] = useState(3);\n  const total = 10;\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Cmp currentPage={page} totalPages={total} />\n    </div>\n  );\n}"
