    "librarySlug": "origin-ui",
    "code": "import { Button } from \"@/components/ui/button\";\nimport {\n  Pagination,\n  PaginationContent,\n  PaginationItem,\n} from \"@/components/ui/pagination\";\n\ntype PaginationProps = {\n  currentPage: number;\n  totalPages: number;\n};\n\nexport default function Component({\n  currentPage,\n  totalPages,\n}: PaginationProps) {\n  return (\n    <div className=\"flex items-center justify-between gap-3\">\n      <p aria-live=\"polite\" className=\"grow text-muted-foreground text-sm\">\n        Page <span className=\"text-foreground\">{currentPage}</span> of{\" \"}\n        <span className=\"text-foreground\">{totalPages}</span>\n      </p>\n      <Pagination className=\"w-auto\">\n        <PaginationContent className=\"gap-3\">\n          <PaginationItem>\n            <Button\n              aria-disabled={currentPage === 1 ? true : undefined}\n              asChild\n              className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n              role={currentPage === 1 ? \"link\" : undefined}\n              variant=\"outline\"\n            >\n              <a\n                href={\n                  currentPage === 1 ? undefined : `#/page/${currentPage - 1}`\n                }\n              >\n                Previous\n              </a>\n            </Button>\n          </PaginationItem>\n          <PaginationItem>\n            <Button\n              aria-disabled={currentPage === totalPages ? true : undefined}\n              asChild\n              className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n              role={currentPage === totalPages ? \"link\" : undefined}\n              variant=\"outline\"\n            >\n              <a\n                href={\n                  currentPage === totalPages\n                    ? undefined\n                    : `#/page/${currentPage + 1}`\n                }\n              >\n                Next\n              </a>\n            </Button>\n          </PaginationItem>\n        </PaginationContent>\n      </Pagination>\n    </div>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { useState } from \"react\";\n\nimport Cmp from \"@/registry/origin-ui/comp-458\";\n\nexport default function Demo() {\n  const [page, setPage] = useState(3);\n  const total = 10;\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Cmp currentPage={page} totalPages={total} />\n    </div>\n  );\n}"
