    "code": "import { ChevronLeftIcon, ChevronRightIcon } from \"lucide-react\";\n\nimport { usePagination } from \"@/registry/origin-ui/use-pagination\";\nimport {\n  Pagination,\n  PaginationContent,\n  PaginationEllipsis,\n  PaginationItem,\n  PaginationLink,\n} from \"@/components/ui/pagination\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/components/ui/select\";\n\ntype PaginationProps = {\n  currentPage: number;\n  totalPages: number;\n  paginationItemsToDisplay?: number;\n};\n\nexport default function Component({\n  currentPage,\n  totalPages,\n  paginationItemsToDisplay = 5,\n}: PaginationProps) {\n  const { pages, showLeftEllipsis, showRightEllipsis } = usePagination({\n    currentPage,\n    paginationItemsToDisplay,\n    totalPages,\n  });\n\n  return (\n    <div className=\"flex items-center justify-between gap-3\">\n      {/* Page number information */}\n      <p\n        aria-live=\"polite\"\n        className=\"flex-1 whitespace-nowrap text-muted-foreground text-sm\"\n      >\n        Page <span className=\"text-foreground\">{currentPage}</span> of{\" \"}\n        <span className=\"text-foreground\">{totalPages}</span>\n      </p>\n\n      {/* Pagination */}\n      <div className=\"grow\">\n        <Pagination>\n          <PaginationContent>\n            {/* Previous page button */}\n            <PaginationItem>\n              <PaginationLink\n                aria-disabled={currentPage === 1 ? true : undefined}\n                aria-label=\"Go to previous page\"\n                className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n                href={\n                  currentPage === 1 ? undefined : `#/page/${currentPage - 1}`\n                }\n                role={currentPage === 1 ? \"link\" : undefined}\n              >\n                <ChevronLeftIcon aria-hidden=\"true\" size={16} />\n              </PaginationLink>\n            </PaginationItem>\n\n            {/* Left ellipsis (...) */}\n            {showLeftEllipsis && (\n              <PaginationItem>\n                <PaginationEllipsis />\n              </PaginationItem>\n            )}\n\n            {/* Page number links */}\n            {pages.map((page) => (\n              <PaginationItem key={page}>\n                <PaginationLink\n                  href={`#/page/${page}`}\n                  isActive={page === currentPage}\n                >\n                  {page}\n                </PaginationLink>\n              </PaginationItem>\n            ))}\n\n            {/* Right ellipsis (...) */}\n            {showRightEllipsis && (\n              <PaginationItem>\n                <PaginationEllipsis />\n              </PaginationItem>\n            )}\n\n            {/* Next page button */}\n            <PaginationItem>\n              <PaginationLink\n                aria-disabled={currentPage === totalPages ? true : undefined}\n                aria-label=\"Go to next page\"\n                className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n                href={\n                  currentPage === totalPages\n                    ? undefined\n                    : `#/page/${currentPage + 1}`\n                }\n                role={currentPage === totalPages ? \"link\" : undefined}\n              >\n                <ChevronRightIcon aria-hidden=\"true\" size={16} />\n              </PaginationLink>\n            </PaginationItem>\n          </PaginationContent>\n        </Pagination>\n      </div>\n\n      {/* Results per page */}\n      <div className=\"flex flex-1 justify-end\">\n        <Select aria-label=\"Results per page\" defaultValue=\"10\">\n          <SelectTrigger\n            className=\"w-fit whitespace-nowrap\"\n            id=\"results-per-page\"\n          >\n            <SelectValue placeholder=\"Select number of results\" />\n          </SelectTrigger>\n          <SelectContent>\n            <SelectItem value=\"10\">10 / page</SelectItem>\n            <SelectItem value=\"20\">20 / page</SelectItem>\n            <SelectItem value=\"50\">50 / page</SelectItem>\n            <SelectItem value=\"100\">100 / page</SelectItem>\n          </SelectContent>\n        </Select>\n      </div>\n    </div>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { useState } from \"react\";\n\nimport Cmp from \"@/registry/origin-ui/comp-462\";\n\nexport default function Demo() {\n  const [page, setPage] = useState(3);\n  const total = 10;\n  return (\n    <div className=\"w-full max-w-2xl\">\n      <Cmp currentPage={page} totalPages={total} paginationItemsToDisplay={5} />\n    </div>\n  );\n}"
