    "code": "\"use client\";\n\nimport { useState } from \"react\";\nimport type { DropdownNavProps, DropdownProps } from \"react-day-picker\";\n\nimport { Calendar } from \"@/components/ui/calendar\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/components/ui/select\";\n\nexport default function Component() {\n  const [date, setDate] = useState<Date | undefined>(new Date());\n\n  const handleCalendarChange = (\n    _value: string | number,\n    _e: React.ChangeEventHandler<HTMLSelectElement>,\n  ) => {\n    const _event = {\n      target: {\n        value: String(_value),\n      },\n    } as React.ChangeEvent<HTMLSelectElement>;\n    _e(_event);\n  };\n\n  return (\n    <div>\n      <Calendar\n        captionLayout=\"dropdown-years\"\n        className=\"rounded-md border p-2\"\n        components={{\n          DropdownNav: (props: DropdownNavProps) => {\n            return (\n              <div className=\"flex w-full items-center justify-center gap-3 [&>span]:font-medium [&>span]:text-sm\">\n                {props.children}\n              </div>\n            );\n          },\n          YearsDropdown: (props: DropdownProps) => {\n            return (\n              <Select\n                onValueChange={(value) => {\n                  if (props.onChange) {\n                    handleCalendarChange(value, props.onChange);\n                  }\n                }}\n                value={String(props.value)}\n              >\n                <SelectTrigger className=\"h-8 w-fit font-medium\">\n                  <SelectValue />\n                </SelectTrigger>\n                <SelectContent className=\"max-h-[min(26rem,var(--radix-select-content-available-height))]\">\n                  {props.options?.map((option) => (\n                    <SelectItem\n                      disabled={option.disabled}\n                      key={option.value}\n                      value={String(option.value)}\n                    >\n                      {option.label}\n                    </SelectItem>\n                  ))}\n                </SelectContent>\n              </Select>\n            );\n          },\n        }}\n        defaultMonth={new Date()}\n        mode=\"single\"\n        onSelect={setDate}\n        selected={date}\n        startMonth={new Date(1980, 6)}\n      />\n      <p\n        aria-live=\"polite\"\n        className=\"mt-4 text-center text-muted-foreground text-xs\"\n        role=\"region\"\n      >\n        Yearly select + nav -{\" \"}\n        <a\n          className=\"underline hover:text-foreground\"\n          href=\"https://daypicker.dev/\"\n          rel=\"noreferrer noopener nofollow\"\n          target=\"_blank\"\n        >\n          React DayPicker\n        </a>\n      </p>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-498\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
