    "code": "\"use client\";\n\nimport { addDays } from \"date-fns\";\nimport { useState } from \"react\";\nimport type { DateRange } from \"react-day-picker\";\n\nimport { Calendar } from \"@/components/ui/calendar\";\n\nexport default function Component() {\n  const today = new Date();\n  const [date, setDate] = useState<DateRange | undefined>({\n    from: today,\n    to: addDays(today, 25),\n  });\n\n  return (\n    <div>\n      <Calendar\n        className=\"rounded-md border p-2\"\n        classNames={{\n          month:\n            \"relative first-of-type:before:hidden before:absolute max-sm:before:inset-x-2 max-sm:before:h-px max-sm:before:-top-2 sm:before:inset-y-2 sm:before:w-px before:bg-border sm:before:-left-4\",\n          months: \"gap-8\",\n        }}\n        mode=\"range\"\n        numberOfMonths={2}\n        onSelect={setDate}\n        pagedNavigation\n        selected={date}\n        showOutsideDays={false}\n      />\n      <p\n        aria-live=\"polite\"\n        className=\"mt-4 text-center text-muted-foreground text-xs\"\n        role=\"region\"\n      >\n        Two months calendar -{\" \"}\n        <a\n          className=\"underline hover:text-foreground\"\n          href=\"https://daypicker.dev/\"\n          rel=\"noreferrer noopener nofollow\"\n          target=\"_blank\"\n        >\n          React DayPicker\n        </a>\n      </p>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-508\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
