    "code": "\"use client\";\n\nimport { addDays } from \"date-fns\";\nimport { useState } from \"react\";\nimport type { DateRange } from \"react-day-picker\";\n\nimport { Calendar } from \"@/components/ui/calendar\";\n\nexport default function Component() {\n  const today = new Date();\n  const [date, setDate] = useState<DateRange | undefined>({\n    from: today,\n    to: addDays(today, 48),\n  });\n\n  return (\n    <div>\n      <Calendar\n        className=\"rounded-md border p-2\"\n        classNames={{\n          month:\n            \"relative first-of-type:before:hidden before:absolute max-md:before:inset-x-2 max-md:before:h-px max-md:before:-top-4 md:before:inset-y-2 md:before:w-px before:bg-border md:before:-left-4\",\n          months: \"sm:flex-col md:flex-row gap-8\",\n        }}\n        mode=\"range\"\n        numberOfMonths={3}\n        onSelect={setDate}\n        pagedNavigation\n        selected={date}\n        showOutsideDays={false}\n      />\n      <p\n        aria-live=\"polite\"\n        className=\"mt-4 text-center text-muted-foreground text-xs\"\n        role=\"region\"\n      >\n        Three months calendar -{\" \"}\n        <a\n          className=\"underline hover:text-foreground\"\n          href=\"https://daypicker.dev/\"\n          rel=\"noreferrer noopener nofollow\"\n          target=\"_blank\"\n        >\n          React DayPicker\n        </a>\n      </p>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-509\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
