    "code": "import {\n  HashIcon,\n  HouseIcon,\n  MailIcon,\n  SearchIcon,\n  UsersRound,\n} from \"lucide-react\";\nimport { useId } from \"react\";\n\nimport Logo from \"@/registry/origin-ui/logo\";\nimport NotificationMenu from \"@/registry/origin-ui/notification-menu\";\nimport UserMenu from \"@/registry/origin-ui/user-menu\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport {\n  NavigationMenu,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n} from \"@/components/ui/navigation-menu\";\nimport {\n  Popover,\n  PopoverContent,\n  PopoverTrigger,\n} from \"@/components/ui/popover\";\n\nconst _teams = [\"Acme Inc.\", \"coss.com\", \"Junon\"];\n\n// Navigation links array to be used in both desktop and mobile menus\nconst navigationLinks = [\n  { href: \"#\", icon: HouseIcon, label: \"Home\" },\n  { href: \"#\", icon: HashIcon, label: \"Hash\" },\n  { href: \"#\", icon: UsersRound, label: \"Groups\" },\n];\n\nexport default function Component() {\n  const id = useId();\n\n  return (\n    <header className=\"border-b px-4 md:px-6\">\n      <div className=\"flex h-16 items-center justify-between gap-4\">\n        {/* Left side */}\n        <div className=\"flex flex-1 items-center gap-2\">\n          {/* Mobile menu trigger */}\n          <Popover>\n            <PopoverTrigger asChild>\n              <Button\n                className=\"group size-8 md:hidden\"\n                size=\"icon\"\n                variant=\"ghost\"\n              >\n                <svg\n                  className=\"pointer-events-none\"\n                  fill=\"none\"\n                  height={16}\n                  stroke=\"currentColor\"\n                  strokeLinecap=\"round\"\n                  strokeLinejoin=\"round\"\n                  strokeWidth=\"2\"\n                  viewBox=\"0 0 24 24\"\n                  width={16}\n                  xmlns=\"http://www.w3.org/2000/svg\"\n                >\n                  <path\n                    className=\"-translate-y-[7px] origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-x-0 group-aria-expanded:translate-y-0 group-aria-expanded:rotate-315\"\n                    d=\"M4 12L20 12\"\n                  />\n                  <path\n                    className=\"origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.8)] group-aria-expanded:rotate-45\"\n                    d=\"M4 12H20\"\n                  />\n                  <path\n                    className=\"origin-center translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-y-0 group-aria-expanded:rotate-135\"\n                    d=\"M4 12H20\"\n                  />\n                </svg>\n              </Button>\n            </PopoverTrigger>\n            <PopoverContent align=\"start\" className=\"w-48 p-1 md:hidden\">\n              <NavigationMenu className=\"max-w-none *:w-full\">\n                <NavigationMenuList className=\"flex-col items-start gap-0 md:gap-2\">\n                  {navigationLinks.map((link, _index) => {\n                    const Icon = link.icon;\n                    return (\n                      <NavigationMenuItem className=\"w-full\" key={link.label}>\n                        <NavigationMenuLink\n                          className=\"flex-row items-center gap-2 py-1.5\"\n                          href={link.href}\n                        >\n                          <Icon\n                            aria-hidden=\"true\"\n                            className=\"text-muted-foreground\"\n                            size={16}\n                          />\n                          <span>{link.label}</span>\n                        </NavigationMenuLink>\n                      </NavigationMenuItem>\n                    );\n                  })}\n                </NavigationMenuList>\n              </NavigationMenu>\n            </PopoverContent>\n          </Popover>\n          <div className=\"flex items-center gap-6\">\n            <a className=\"text-primary hover:text-primary/90\" href=\"#\">\n              <Logo />\n            </a>\n            {/* Search form */}\n            <div className=\"relative\">\n              <Input\n                className=\"peer h-8 ps-8 pe-2\"\n                id={id}\n                placeholder=\"Search...\"\n                type=\"search\"\n              />\n              <div className=\"pointer-events-none absolute inset-y-0 start-0 flex items-center justify-center ps-2 text-muted-foreground/80 peer-disabled:opacity-50\">\n                <SearchIcon size={16} />\n              </div>\n            </div>\n          </div>\n        </div>\n        {/* Middle area */}\n        <NavigationMenu className=\"max-md:hidden\">\n          <NavigationMenuList className=\"gap-2\">\n            {navigationLinks.map((link, _index) => {\n              const Icon = link.icon;\n              return (\n                <NavigationMenuItem key={link.label}>\n                  <NavigationMenuLink\n                    className=\"flex size-8 items-center justify-center p-1.5\"\n                    href={link.href}\n                    title={link.label}\n                  >\n                    <Icon aria-hidden=\"true\" />\n                    <span className=\"sr-only\">{link.label}</span>\n                  </NavigationMenuLink>\n                </NavigationMenuItem>\n              );\n            })}\n          </NavigationMenuList>\n        </NavigationMenu>\n        {/* Right side */}\n        <div className=\"flex flex-1 items-center justify-end gap-4\">\n          <div className=\"flex items-center gap-2\">\n            {/* Messages */}\n            <Button\n              aria-label=\"Open notifications\"\n              className=\"relative size-8 rounded-full text-muted-foreground shadow-none\"\n              size=\"icon\"\n              variant=\"ghost\"\n            >\n              <MailIcon aria-hidden=\"true\" size={16} />\n              <div\n                aria-hidden=\"true\"\n                className=\"absolute top-0.5 right-0.5 size-1 rounded-full bg-primary\"\n              />\n            </Button>\n            {/* Notification menu */}\n            <NotificationMenu />\n          </div>\n          {/* User menu */}\n          <UserMenu />\n        </div>\n      </div>\n    </header>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-585\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
