    "librarySlug": null,
    "code": "\"use client\";\n\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport { ShaderToy } from \"@/registry/inspira-react/shader-toy\";\n\nconst THUNDERSTORM_SHADER = `\n// ShaderToy: https://www.shadertoy.com/view/W3d3z7\n\nfloat n(vec2 p) {\n    return sin(p.x * 3. + sin(p.y * 2.7)) * cos(p.y * 1.1 + cos(p.x * 2.3));\n}\n\nfloat f(vec2 p) {\n    float v = 0., a = 1.;\n    for (int i = 0; i < 9; i++)\n        v += n(p) * a, p *= 2., a *= .5;\n    return v;\n}\n\nvoid mainImage(out vec4 o, vec2 p) {\n    p = (p - iResolution.xy) / iResolution.y;\n    float t = iTime * iSpeed;\n    vec3 c = vec3(.1, .2, .6) / (length(p + vec2(sin(t * 2.2), sin(t)) + f(p + t * .3 + 1.)) * 2.1)\n        + vec3(.7, .5, .2) / (length(p + vec2(cos(t * 2.), sin(t)) + f(p + t * .3 + 1.)) * 2.1)\n        + vec3(1.3) / (length(p + vec2(sin(t * 1.2), cos(t * 1.3)) + f(p + t * .3 + 2.)) * 2.1);\n    o = vec4(c * .8 / (3.5 + c), 1);\n}\n`;\n\nexport interface BgThunderstormProps {\n  className?: string;\n  hue?: number;\n  saturation?: number;\n  brightness?: number;\n  speed?: number;\n  mouseSensitivity?: number;\n  damping?: number;\n  noise?: { opacity: number; scale: number };\n}\n\nexport function BgThunderstorm({\n  className,\n  hue = 0,\n  saturation = 1,\n  brightness = 1,\n  speed = 1,\n  mouseSensitivity = 0.5,\n  damping = 1,\n  noise,\n}: BgThunderstormProps) {\n  return (\n    <div className={cn(\"absolute inset-0\", className)}>\n      <ShaderToy\n        shaderCode={THUNDERSTORM_SHADER}\n        hue={hue}\n        saturation={saturation}\n        brightness={brightness}\n        speed={speed}\n        mouseSensitivity={mouseSensitivity}\n        damping={damping}\n        noise={noise}\n      />\n    </div>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { BgThunderstorm } from \"@/registry/inspira-react/bg-thunderstorm\";\n\nexport default function BgThunderstormDemo() {\n  return (\n    <div className=\"relative h-[600px] w-full overflow-hidden rounded-xl bg-black\">\n      <BgThunderstorm hue={0} saturation={1} brightness={1} speed={1} />\n      <div className=\"relative z-10 flex h-full items-center justify-center\">\n        <p className=\"text-2xl font-semibold text-white drop-shadow\">Thunderstorm</p>\n      </div>\n    </div>\n  );\n}"
