    "source": null,
    "library": null,
    "librarySlug": null,
    "code": "\"use client\";\n\nimport React from \"react\";\nimport { cn } from \"@/lib/utils\";\n\ninterface GradientButtonProps {\n  borderWidth?: number;\n  colors?: string[];\n  duration?: number;\n  borderRadius?: number;\n  blur?: number;\n  className?: string;\n  bgColor?: string;\n  children?: React.ReactNode;\n  onClick?: React.MouseEventHandler<HTMLButtonElement>;\n}\n\nexport function GradientButton({\n  colors = [\"#FF0000\", \"#FFA500\", \"#FFFF00\", \"#008000\", \"#0000FF\", \"#4B0082\", \"#EE82EE\", \"#FF0000\"],\n  duration = 2500,\n  borderWidth = 2,\n  borderRadius = 8,\n  blur = 4,\n  bgColor = \"#000\",\n  className,\n  children,\n  onClick,\n}: GradientButtonProps) {\n  const allColors = colors.join(\", \");\n\n  const buttonStyle: React.CSSProperties = {\n    padding: `${borderWidth}px`,\n    borderRadius: `${borderRadius}px`,\n    position: \"relative\",\n    display: \"inline-flex\",\n    minHeight: \"40px\",\n    minWidth: \"112px\",\n    alignItems: \"center\",\n    justifyContent: \"center\",\n    overflow: \"hidden\",\n  };\n\n  const beforeStyle: React.CSSProperties = {\n    content: '\"\"',\n    position: \"absolute\",\n    inset: \"-200%\",\n    background: `conic-gradient(${allColors})`,\n    animation: `rotate-rainbow ${duration}ms linear infinite`,\n    filter: `blur(${blur}px)`,\n  };\n\n  const contentStyle: React.CSSProperties = {\n    borderRadius: `${borderRadius}px`,\n    backgroundColor: bgColor,\n    zIndex: 0,\n    display: \"inline-flex\",\n    width: \"100%\",\n    height: \"100%\",\n    alignItems: \"center\",\n    justifyContent: \"center\",\n    padding: \"8px 16px\",\n    position: \"relative\",\n  };\n\n  return (\n    <>\n      <style>{`\n        @keyframes rotate-rainbow {\n          0% { transform: rotate(0deg); }\n          100% { transform: rotate(360deg); }\n        }\n        .gradient-btn-before::before {\n          content: \"\";\n          position: absolute;\n          inset: -200%;\n          background: conic-gradient(${allColors});\n          animation: rotate-rainbow ${duration}ms linear infinite;\n          filter: blur(${blur}px);\n        }\n      `}</style>\n      <button\n        className={cn(\"gradient-btn-before relative overflow-hidden\", className)}\n        style={buttonStyle}\n        onClick={onClick}\n      >\n        <span style={beforeStyle as React.CSSProperties} aria-hidden=\"true\" />\n        <span style={contentStyle}>{children}</span>\n      </button>\n    </>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { GradientButton } from \"@/registry/inspira-react/gradient-button\";\n\nexport default function GradientButtonDemo() {\n  return (\n    <div className=\"flex flex-col items-center justify-center gap-6 p-12 bg-black min-h-[200px]\">\n      <GradientButton>\n        <span className=\"text-white font-semibold\">Click me</span>\n      </GradientButton>\n      <GradientButton\n        colors={[\"#06b6d4\", \"#3b82f6\", \"#8b5cf6\", \"#ec4899\", \"#06b6d4\"]}\n        duration={1500}\n        borderRadius={24}\n        bgColor=\"#0f172a\"\n      >\n        <span className=\"text-white font-semibold\">Custom Colors</span>\n      </GradientButton>\n    </div>\n  );\n}"
