    "code": "\"use client\"\n\nimport { useState, useRef, useCallback, type CSSProperties, type ReactNode } from \"react\"\nimport { cn } from \"@/lib/utils\"\n\ninterface LinkPreviewProps {\n  className?: string\n  linkClass?: string\n  width?: number\n  height?: number\n  isStatic?: boolean\n  imageSrc?: string\n  url?: string\n  children?: ReactNode\n}\n\nexport function LinkPreview({\n  className,\n  linkClass,\n  width = 200,\n  height = 125,\n  isStatic = false,\n  imageSrc = \"\",\n  url = \"\",\n  children,\n}: LinkPreviewProps) {\n  const [isVisible, setIsVisible] = useState(false)\n  const [hasPopped, setHasPopped] = useState(false)\n  const [mousePos, setMousePos] = useState({ x: 0, y: 0 })\n  const previewRef = useRef<HTMLDivElement>(null)\n  const linkRef = useRef<HTMLAnchorElement>(null)\n\n  const previewSrc = isStatic\n    ? imageSrc\n    : (() => {\n        const params = new URLSearchParams({\n          url: url,\n          screenshot: \"true\",\n          meta: \"false\",\n          embed: \"screenshot.url\",\n          colorScheme: \"light\",\n          \"viewport.isMobile\": \"true\",\n          \"viewport.deviceScaleFactor\": \"1\",\n          \"viewport.width\": String(width * 3),\n          \"viewport.height\": String(height * 3),\n        })\n        return `https://api.microlink.io/?${params.toString()}`\n      })()\n\n  const handleMouseMove = useCallback((e: React.MouseEvent) => {\n    setMousePos({ x: e.clientX, y: e.clientY })\n  }, [])\n\n  const showPreview = useCallback(() => {\n    setIsVisible(true)\n    setTimeout(() => setHasPopped(true), 50)\n  }, [])\n\n  const hidePreview = useCallback(() => {\n    setIsVisible(false)\n    setHasPopped(false)\n  }, [])\n\n  const getPreviewStyle = (): CSSProperties => {\n    const offset = 20\n    const viewportWidth = typeof window !== \"undefined\" ? window.innerWidth : 1024\n\n    let x = mousePos.x - width / 2\n    x = Math.min(Math.max(0, x), viewportWidth - width)\n\n    const linkRect = linkRef.current?.getBoundingClientRect()\n    const y = linkRect ? linkRect.top - height - offset : 0\n\n    return {\n      position: \"fixed\",\n      left: `${x}px`,\n      top: `${y}px`,\n      width: `${width}px`,\n      height: `${height}px`,\n    }\n  }\n\n  return (\n    <div className={cn(\"relative inline-block\", className)}>\n      <a\n        ref={linkRef}\n        href={url}\n        className={cn(\"text-black dark:text-white\", linkClass)}\n        onMouseMove={handleMouseMove}\n        onMouseEnter={showPreview}\n        onMouseLeave={hidePreview}\n      >\n        {children}\n      </a>\n\n      {isVisible && (\n        <div\n          ref={previewRef}\n          className=\"pointer-events-none absolute z-50\"\n          style={getPreviewStyle()}\n        >\n          <div\n            className={cn(\n              \"overflow-hidden rounded-xl shadow-xl\",\n              hasPopped && \"animate-[pop_1000ms_ease_forwards]\",\n              !isStatic && \"will-change-transform\",\n            )}\n          >\n            <div className=\"block rounded-xl border-2 border-transparent bg-white p-1 shadow-lg dark:bg-gray-900\">\n              <img\n                src={previewSrc}\n                width={width}\n                height={height}\n                className=\"size-full rounded-lg object-cover\"\n                style={{ width: `${width}px`, height: `${height}px` }}\n                alt=\"preview\"\n              />\n            </div>\n          </div>\n        </div>\n      )}\n\n      <style>{`\n        @keyframes pop {\n          0% { transform: scale3d(0.26, 0.26, 1); }\n          25% { transform: scale3d(1.1, 1.1, 1); }\n          65% { transform: scale3d(0.98, 0.98, 1); }\n          100% { transform: scale3d(1, 1, 1); }\n        }\n      `}</style>\n    </div>\n  )\n}",
    "demoCode": "\"use client\"\n\nimport { LinkPreview } from \"@/registry/inspira-react/link-preview\"\n\nexport default function LinkPreviewDemo() {\n  return (\n    <div className=\"flex flex-col items-center justify-center gap-6 p-12 min-h-48\">\n      <p className=\"text-neutral-500 text-sm\">Hover over the links below</p>\n      <div className=\"flex gap-8 text-lg font-semibold\">\n        <LinkPreview\n          url=\"https://vercel.com\"\n          isStatic={false}\n          width={200}\n          height={125}\n        >\n          <span className=\"underline cursor-pointer hover:text-blue-600 transition-colors\">\n            Vercel\n          </span>\n        </LinkPreview>\n\n        <LinkPreview\n          url=\"https://github.com\"\n          imageSrc=\"https://github.githubassets.com/assets/GitHub-Mark-ea2971cee799.png\"\n          isStatic={true}\n          width={200}\n          height={125}\n        >\n          <span className=\"underline cursor-pointer hover:text-blue-600 transition-colors\">\n            GitHub (static)\n          </span>\n        </LinkPreview>\n      </div>\n    </div>\n  )\n}"
